import json
with open('data/healthcare_tasks.json') as f:
    data = json.load(f)

# For each of our 5 target constraints, find a task where action_should_succeed=True
# and the constraint is binding
targets = ['claim_within_limits', 'claim_within_coverage_amount', 'provider_authorized', 'policy_active', 'within_enrollment_period']

def find_constraint_in_tree(tree, constraint_name):
    if not tree: return False
    if isinstance(tree, str): return False
    if tree[0] == 'single':
        return tree[1] == constraint_name
    for subtree in tree[1]:
        if find_constraint_in_tree(subtree, constraint_name):
            return True
    return False

for cname in targets:
    print(f'\n=== {cname} ===')
    for action, tasks in data.items():
        for i, task in enumerate(tasks):
            if find_constraint_in_tree(task['constraints_original'], cname) and task['action_should_succeed']:
                # Show the constraint params and key user info
                cp = task['constraint_parameters']
                print(f'  {action}[{i}]: params={cp}')
                print(f'    user_prompt: {task[\"user_prompt\"][:100]}...')
                break
        else:
            continue
        break
